from pathlib import Path
import json,hashlib,datetime
R=Path(__file__).resolve().parents[5];D=Path(__file__).resolve().parent;C=Path('/tmp/medina-source-cache/endocrinologie/E25')
assert not (D/'source-binding.json').exists()
rows=[]
def add(i,url,title,pub,version,file,section,pop,limits,passage,level='section'):
 p=Path(file);p=p if p.is_absolute() else C/p
 assert p.is_file(),p
 rows.append(dict(id=i,url=url,titre=title,editeur=pub,version_annee=version,date_consultation='2026-11-02',section_page=section,population=pop,limites=limits,cache_external=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),lecteur='sol_endocrinologie',read_level=level,passage_paraphrase=passage))
add('S1','https://dam-api.bfs.admin.ch/hub/api/dam/assets/32686265/master','CIM-10-GM E25 et subdivisions','OFS Suisse','2024',R/'nosology/fragments/S05.json','Toutes entrées E25 du catalogue local','Classification','Libellés locaux 2024, aucune certification administrative 2026.','E25.00 est classique, E25.01 tardive/non classique, E25.08 autre déficit enzymatique ; E25.8 ne reçoit pas automatiquement toute cause de virilisation.')
add('S3','https://pmc.ncbi.nlm.nih.gov/articles/PMC8755999/','Congenital adrenal hyperplasia—current insights in pathophysiology, diagnostics and management','Claahsen-van der Grinten, Flück et coll., revue internationale avec auteurs suisses et européens','En ligne 2021 ; volume février 2022','review2021.html','Physiologie et déficits enzymatiques ciblés ; diagnostic néonatal et biochimique ; traitement et surveillance enfants/adultes ; crise ; non classique ; prénatal ; psychosocial ; fertilité masculine','Toutes formes, enfants et adultes','Lecture de sections, pas totalité de la longue revue ; recommandations Endocrine Society 2018 citées, confrontées à FI suisses et BSPED européen. Pas statut réglementaire 2026.','Cortisol diminué et ACTH accrue expliquent accumulation de précurseurs et hyperandrogénie. Remplacement et contrôle androgénique se confrontent à croissance et toxicité. Un résultat 17-hydroxyprogestérone dépend méthode, âge, prélèvement et traitement ; ne pas normaliser systématiquement tous les précurseurs.')
for i,file in [('S4','S4-meta.json'),('S5','S5-meta.json'),('S11','S11-meta.json'),('S13','S13-meta.json')]:
 j=json.loads((C/file).read_text());s=j['resultList']['result'][0]
 notes={'S4':('Femmes avec hyperandrogénie','Revue systématique 2017, données jusqu’à octobre 2016 ; résumé seul, pas fondement unique de prescription.','Le seuil basal historique 6 nmol/L oriente le test, et 30 nmol/L basal ou stimulé soutient le diagnostic, selon méthode. La fréquence 4,2 % concerne les femmes avec excès androgénique sélectionnées.'),'S5':('Forme non classique','Résumé seul, pas doses ni horaire folliculaire déduits.','La réponse de 17-hydroxyprogestérone à la stimulation et le génotypage confortent le diagnostic. Le glucocorticoïde peut induire une insuffisance secondaire et des risques métaboliques/osseux.'),'S11':('Six garçons de quatre familles avec déficit 11β','Petite série pédiatrique, aucune incidence extrapolée.','Hypertension et excès androgénique orientent un déficit 11β ; des inclusions surrénaliennes testiculaires sont possibles dans cette forme aussi.'),'S13':('103 enfants randomisés, 28 semaines','Résumé seul ; essai financé Neurocrine, pas FI suisse ni preuve de bénéfice clinique à long terme.','La réduction de dose glucocorticoïde sous crinecerfont diffère de 23,5 points de pourcentage du placebo à 28 semaines avec contrôle androgénique ; ceci ne remplace pas le cortisol indispensable.')};pop,lim,note=notes[i]
 add(i,'https://pubmed.ncbi.nlm.nih.gov/'+s['pmid']+'/',s['title'],s['authorString'],s['pubYear'],file,'Résumé publié et métadonnées PubMed/Europe PMC',pop,lim,note,'abstract')
add('S7','https://pmc.ncbi.nlm.nih.gov/articles/PMC12210017/','Prevalence of differences of sex development in Switzerland','Étude suisse multicentrique','2025','swissDSD2025.xml','Résumé ; cohorte de naissances 2000–2019','Patients identifiés par dix hôpitaux et huit endocrinologues privés','Cohorte rétrospective sélectionnée ; dénominateur filles pour 46,XX, pas tous nouveau-nés ni toute E25.','Sur 561 patients DSD, 118 sont 46,XX ; l’estimation 46,XX avec hyperplasie congénitale est 1/7500 filles nouveau-nées, non 1/7500 tous nouveau-nés.','abstract')
add('S8','https://kinderklinik.insel.ch/fileadmin/Kinderklinik/Dokumente/PDFs/Neo/Elterninfo/Screening-Flyer2022_Web7_de.pdf','Dépistage néonatal suisse','Insel et dépistage suisse','2022','screen2022.pdf','Pages dépistage et syndrome adrénogénital','Nouveau-nés suisses','Brochure parentale datée ; ni seuil analytique ni protocole de rappel détaillé.','La goutte de sang se prélève au troisième ou quatrième jour selon cette version ; le dépistage permet de reconnaître le syndrome avant la décompensation.')
add('S9','https://www.neoscreening.ch/fr/maladies/','Maladies dépistées : syndrome adrénogénital','Dépistage néonatal suisse','Page consultée 2026-11-02','neoscreen.html','Rubrique syndrome adrénogénital','Nouveau-nés suisses','Chiffre informatif environ 1/9000 nouveau-nés, pas fréquence de toute la catégorie E25 ; un dépistage ne garantit pas zéro séquelle.','Le manque de cortisol expose aux maladies graves, à l’hypoglycémie et à la perte de sel ; les garçons peuvent avoir des organes externes apparemment habituels.')
add('S10','https://endo-ern.eu/wp-content/uploads/2023/04/Adrenogenitales-Syndrom-AGS-Updated.pdf','Adrenogenitales Syndrom : information aux familles','AGS Elterninitiative, hébergement ENDO-ERN Europe','2023','endoernAGS.pdf','Présentation, traitement, urgence, croissance et famille','Parents et patients germanophones','Information patient ; droit allemand non transféré en Suisse ; illustrations tierces non reproduites.','Le remplacement, les adaptations en maladie et la formation de la famille accompagnent le suivi de croissance, de fertilité et de bien-être.')
add('S12','https://pmc.ncbi.nlm.nih.gov/articles/PMC11309900/','Phase 3 trial of crinecerfont in adult congenital adrenal hyperplasia','Auchus et coll., essai multinational financé Neurocrine','2024','S12.html','Résumé, méthodes et résultats principaux ; sponsor et populations','182 adultes randomisés, 24 semaines','Sections ciblées ; bénéfice de dose et biomarqueur, pas statut Swissmedic ni sécurité à long terme ; aucune figure copiée.','La réduction glucocorticoïde était de 27,3 % contre 10,3 %, différence 17 points de pourcentage. L’antagoniste du récepteur CRF1 réduit ACTH/androgènes sans remplacer les hormones déficitaires.')
for i,name,gtin,version,file,note in [('S14','Alkindi granulés 0,5/1/2/5 mg','7680682260010','Février 2025','alkindi.txt','De la naissance à moins de 18 ans, 10–15 mg/m²/j pour hyperplasie en 3–4 prises. Ne pas avaler capsule, mâcher, mélanger à liquide ou passer par sonde. Stress léger double/triple selon plan ; vomissements sévères imposent relais parentéral.'),('S15','Hydrocortisone Galepharm 10 mg comprimé sécable','7680579700018','Août 2025','galepharm.txt','Dose usuelle syndrome adrénogénital 10–30 mg/j ; données Swisspeddose annexées séparées de la FI. Rein sans adaptation, foie sévère peut demander réduction. Ne pas interrompre le remplacement indispensable.'),('S16','Solu-Cortef injectable','7680235330016','Octobre 2025','solucortef.txt','Urgence IV préférée, IM possible ; 100 mg initial en au moins 30 secondes, reprise selon situation. Pas bolus néonatal automatique de 100 mg. La voie intrathécale n’est pas celle de la crise. Allergie et contre-indication IM en purpura thrombopénique sont distinguées.'),('S17','Florinef 0,1 mg comprimé','7680310950184','Mars 2026','florinef.txt','Adulte 0,1 mg trois fois/semaine à 0,2 mg/j ; 0–12 ans 2–5 microgrammes/kg/j. Divergence avec les repères néonataux spécialisés, suivi pression/rénine/électrolytes. Grossesse seulement si nécessaire ; ne pas allaiter selon cette FI.'),('S18','Synacthen injectable immédiat 0,25 mg/ml','7680317230012','Juin 2023','synacthen.txt','Test adulte 0,25 mg IM/IV, cortisol avant et exactement à 30 min ; anaphylaxie, surveillance 30 min. Contre-indication thérapeutique du syndrome adrénogénital distincte de son usage diagnostique. Posologie pédiatrique non étudiée dans cette FI.')]:
 add(i,'https://amiko.oddb.org/fr/fi?gtin='+gtin,'Information professionnelle suisse '+name,'Swissmedic/AIPS via AmiKo',version,file,'Indications, posologie, contre-indications, précautions, interactions, grossesse/allaitement ciblées','Produit exact, âges et situations explicités','La FI exacte ne vaut pas une autre formulation ni un protocole syndromique ; la dose maximale n’est pas inventée si non définie.',note)
add('S19','https://openstax.org/books/anatomy-and-physiology-2e/pages/17-6-the-adrenal-glands','The adrenal glands','OpenStax','2e §17.6','openstax.html','Situation, cortex, médulla et couches corticales','Science normale','Pédagogie américaine, pas recommandation clinique. L’aldostérone n’est pas décrite comme principalement ACTH dépendante. Licence de figure historique traitée séparément.','Cortex externe en zones glomérulée, fasciculée et réticulée ; médulla interne à catécholamines. La figure normale ne montre aucun déficit individuel.')
add('S20','https://smifk-cims.ch/download_file/view/c28daec4-78b0-4a6e-a198-00ca757191fc/261','PROFILES','CIMS Suisse','2017','/workspace/medina-source-cache/C85/profiles2017-official.pdf','Situations examen organes génitaux, pression, enfance croissance/puberte','Formation médicale suisse','Lien pédagogique, aucune question officielle ni correspondance CIM officielle.','Organes génitaux externes atypiques, pression anormale et croissance/puberte inhabituelles appellent un raisonnement et une communication adaptés.')
add('S21','https://pmc.ncbi.nlm.nih.gov/articles/PMC10646833/','Emergency and perioperative management of adrenal insufficiency in children and young people: BSPED consensus guidance','Mushtaq et coll., BSPED Royaume-Uni','2023','bsped.html','Résumé, méthodes, sick day, tableau 3 crise, fludrocortisone','Enfants et adolescents avec insuffisance surrénale','Consensus européen, preuves pédiatriques limitées ; ne remplace pas protocole suisse ni FI du produit. Autre article de résumé 2024 distingué.','Crise : hydrocortisone IM/IV 25 mg avant un an, 50 mg de 1 à 5 ans, 100 mg dès 6 ans ; options au poids et suivi hospitalier. Maladie orale environ 30 mg/m²/j en quatre prises. Ne pas doubler automatiquement la fludrocortisone.')
add('S22','https://pmc.ncbi.nlm.nih.gov/articles/PMC7609334/','EMQN best practice guidelines for molecular genetic testing and reporting of 21-hydroxylase deficiency','Baumgartner-Parzer et coll., EMQN Europe','2020','emqn.html','Résumé, introduction, indications, échantillons parentaux, diagnostic prénatal, locus et méthodes ciblées','Diagnostic génétique familial CYP21A2','Lecture ciblée ; ancienneté et législation nationale à vérifier. Pas disponibilité suisse de tout test.','Le pseudogène proche, conversions et variations du nombre de copies rendent l’analyse complexe ; séquençage et dosage de copies se complètent. Les parents aident à établir cis/trans. Traitement prénatal expérimental, pas routine.')
