(P/'sources.json').write_text(json.dumps({'sources':rows},ensure_ascii=False,indent=2)+'\n');(D/'source-ledger.json').write_text((P/'sources.json').read_text())
labels=['Question clinique et examen','Définition et périmètre','Classification','Épidémiologie suisse puis Europe','Normal puis pathologique','Étiologies et risques','Anamnèse','Examen clinique','Urgence et gravité','Explorations','Différentiels','Traitement suisse et FI','Complications et pronostic','Suivi et prévention','Populations particulières','Aspects administratifs suisses','Critères formels','Paramètres chiffrés','Sous-codes','Objectifs et pièges']
ss=['S20 S21','S1 S3','S1 S3','S7 S9 S22','S3 S19','S3 S22','S3 S10','S3 S21','S16 S21','S3 S4 S18 S22','S3 S4','S14 S15 S16 S17 S21','S3 S12 S13','S3 S10 S21','S3 S14 S17','S1 S22','S3 S4 S22','S14 S17 S18 S21','S1','S20 S21']
t='# Recherche E25 — Anomalies génito-surrénaliennes\n\nLecture ciblée réelle par sol_endocrinologie le 2 novembre 2026. E25.00, E25.01, E25.08, E25.09, E25.8 et E25.9 distingués. Pas adoption automatique de l’ancien dossier.\n\n## Matrice de complétude\n\n| rubrique | statut | sources |\n|---|---|---|\n'
for n,(l,s) in enumerate(zip(labels,ss),1):t+=f'| {n}. {l} | ✔ | '+', '.join('['+i+']' for i in s.split())+' ; portée et limites des lectures ci-dessous. |\n'
t+='\n## Arbitrages avant rédaction\n\nNe pas prescrire 100 mg à tout nouveau-né en crise : distinguer consensus européen par âge/poids et FI produit. Ne pas confondre référence de maladie orale et entretien. Ne pas tripler automatiquement le minéralocorticoïde. Conserver la divergence entre FI Florinef 2–5 µg/kg/j et revue néonatale 100–200 µg/j ; expertise spécialisée obligatoire, aucune dose composite. Aucun seuil moderne universel 17-hydroxyprogestérone ou cortisol n’est déduit des anciens seuils immunologiques. Les données de femmes hyperandrogéniques ne sont pas une prévalence générale ; 1/7500 filles et 1/9000 nouveau-nés sont des dénominateurs différents. Ne pas affirmer une disponibilité suisse 2026 du crinecerfont à partir du seul essai ou d’une recherche vide. Les procédures génitales et le prénatal restent discutés, consentement/autonomie respectés ; aucune loi allemande importée. Les tumeurs, ovaires polykystiques et autres variations du développement restent des différentiels à coder selon diagnostic.\n\n## Sources réellement lues et limites\n\n'
for s in rows:t+=f"### [{s['id']}] {s['titre']}\n\n{s['section_page']}. {s['passage_paraphrase']} Population : {s['population']}. Limites : {s['limites']}\n\n"
(P/'recherche.md').write_text(t)
(D/'source-cache-manifest.json').write_text(json.dumps(dict(created_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),full_sources_outside_git=True,sources=[dict(id=s['id'],path=s['cache_external'],sha256=s['sha256'],read_level=s['read_level']) for s in rows]),ensure_ascii=False,indent=2)+'\n')
print(len(rows),'sources')
